# More destination pages. Edit the text here, upload this file to GitHub, and Netlify rebuilds the site.
# Each location needs: slug, name, group, places, intro, rows (4 x period/demand/what we do), pains (3 or 4), and one extra question.
# Demand notes are general patterns. Exact dates change each year, so we plan from the live calendar.

def L(slug, name, group, places, intro, rows, pains, q, a, h1=None, kind="hotels"):
    return dict(
        slug=slug, name=name, group=group, places=places,
        title="Hotel Consultant & Revenue Management in %s | Revotel" % name,
        desc="Hotel revenue management, OTA distribution and launch consulting for %s in %s. Plan around: %s." % (kind, name, rows[0][1].rstrip(".").lower()),
        h1=h1 or "Hotel revenue management in %s" % name,
        intro=intro, rows=rows, pains=pains,
        faqs=[("Do you work with %s in %s?" % (kind, name), "Yes. Send us the property name, room count and what you need, and we will reply with questions and a proposal after a short call."),
              (q, a),
              ("Is the work done remotely?", "Yes. Rates and channel work run through your systems, with regular calls to review results. For a new property we can also plan a visit.")])

